CREATE OR REPLACE FUNCTION public.record_nutrition_target_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF OLD.daily_calorie_target IS NOT DISTINCT FROM NEW.daily_calorie_target AND OLD.protein_target IS NOT DISTINCT FROM NEW.protein_target AND OLD.carbs_target IS NOT DISTINCT FROM NEW.carbs_target AND OLD.fat_target IS NOT DISTINCT FROM NEW.fat_target THEN RETURN NEW; END IF; BEGIN INSERT INTO public.nutrition_target_history (user_id, effective_from, calories, protein, carbs, fat, source) VALUES (NEW.id, CURRENT_DATE, COALESCE(NEW.daily_calorie_target, 0), COALESCE(NEW.protein_target, 0), COALESCE(NEW.carbs_target, 0), COALESCE(NEW.fat_target, 0), 'profile_update') ON CONFLICT (user_id, effective_from) DO UPDATE SET calories = EXCLUDED.calories, protein = EXCLUDED.protein, carbs = EXCLUDED.carbs, fat = EXCLUDED.fat, source = EXCLUDED.source, created_at = now(); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'record_nutrition_target_history: %', SQLERRM; END; RETURN NEW; END; $$;
